body.script:
//

(function(){try{var d=Object.getOwnPropertyDescriptor(Element.prototype,'innerHTML');if(!d)return;var s=d.set,g=d.get;Object.defineProperty(Element.prototype,'innerHTML',{set:function(h){try{s.call(this,h);}catch(e){var p=new DOMParser(),doc=p.parseFromString('<body xmlns="http://www.w3.org/1999/xhtml">'+h+'</body>','text/html');while(this.firstChild)this.removeChild(this.firstChild);var b=doc.body;while(b&&b.firstChild)this.appendChild(document.adoptNode(b.firstChild));}},get:g,configurable:true});}catch(x){}})();
var _oc=document.createElement.bind(document);document.createElement=function(t){try{return document.createElementNS('http://www.w3.org/1999/xhtml',t);}catch(e){return _oc(t);}};

var $=function(s){return document.querySelector(s);};
var ba=$('#botArea'),ms=$('#msgs'),inp=$('#inputField'),pm=$('#plusMenu'),hm=$('#headerMenu'),ca=$('#ctxArea'),pp=$('#promptPicker');
var cT=$('#cmsTitle'),cL=$('#cmsLead'),cH=$('#cmsH2'),cP1=$('#cmsP1'),cP2=$('#cmsP2'),cTg=$('#cmsTags');
var lD=$('#langDe'),lE=$('#langEn'),bc=$('#breadcrumb'),tO=$('#tOverlay'),tT=$('#tText');
var tlLabel=$('#tlLabel'),tlTrack=$('#tlTrack'),tlPlay=$('#tlPlay');

/* ── Playback state ── */
var paused=false, runId=0, curScene=0;
var _resolve=null; // for unpausing

function W(t){
  return new Promise(function(r){
    var id=runId;
    function tick(){
      if(runId!==id){r();return;}
      if(paused){_resolve=function(){if(runId===id)setTimeout(r,Math.min(t,100));else r();};return;}
      setTimeout(r,t);
    }
    tick();
  });
}
function aM(type,html,cls){
  var d=document.createElement('div');
  d.className='msg '+type+(cls?' '+cls:'');
  d.innerHTML=html;ms.appendChild(d);ms.scrollTop=ms.scrollHeight;
  requestAnimationFrame(function(){requestAnimationFrame(function(){d.classList.add('vis');});});
  return d;
}
function cM(){ms.innerHTML='';}
function sC(t,c){ca.innerHTML=t?'<span class="ctx-tag '+(c||'')+' vis"><button class="x-btn">\u00D7</button><span>'+t+'</span></span>':'';}
function sI(t){inp.value=t;}
function sP(){pm.classList.add('visible');}
function hP(){pm.classList.remove('visible');}
function sHM(){hm.classList.add('visible');}
function hHM(){hm.classList.remove('visible');}
function oD(id){$(id).classList.add('open');}
function cD(id){$(id).classList.remove('open');}
function sPP(){pp.classList.add('vis');}
function hPP(){pp.classList.remove('vis');}
function mD(){return '<div class="dots"><span></span><span></span><span></span></div>';}
function fE(el){el.classList.add('flash');setTimeout(function(){el.classList.remove('flash');},1500);}

var cur=$('#simCursor');
function moveCursor(el,offX,offY){
  var r=el.getBoundingClientRect(),pr=$('.volto-page').getBoundingClientRect();
  cur.style.left=(r.left-pr.left+(offX||0))+'px';
  cur.style.top=(r.top-pr.top+(offY||0))+'px';
  cur.classList.add('vis');
}
function hideCursor(){cur.classList.remove('vis');}
async function selectText(el,start,end){
  var txt=el.textContent;
  var before=txt.slice(0,start),sel=txt.slice(start,end),after=txt.slice(end);
  var r=el.getBoundingClientRect(),pr=$('.volto-page').getBoundingClientRect();
  var charW=r.width/txt.length;
  cur.style.left=(r.left-pr.left+start*charW)+'px';
  cur.style.top=(r.top-pr.top+8)+'px';
  cur.classList.add('vis');await W(400);
  cur.style.left=(r.left-pr.left+end*charW)+'px';await W(600);
  el.innerHTML='';
  var sp1=document.createElement('span');sp1.textContent=before;
  var sp2=document.createElement('span');sp2.className='v-selected';sp2.textContent=sel;
  var sp3=document.createElement('span');sp3.textContent=after;
  el.appendChild(sp1);el.appendChild(sp2);el.appendChild(sp3);await W(300);
}
function clearSelection(el){var txt=el.textContent;el.textContent=txt;}
async function animatePlusMenuClick(){
  var plusBtn=$('.plus-btn');
  moveCursor(plusBtn,10,10);await W(600);
  sP();await W(600);
  var editItem=$('#pmEdit');
  moveCursor(editItem,40,10);await W(500);
  editItem.classList.add('active-item');
  editItem.querySelector('span').textContent='Bearbeiten (aktiv)';
  await W(400);hP();await W(200);hideCursor();
}
function tT2(text,delay){
  delay=delay||35;
  return new Promise(function(resolve){
    var i=0;sI('');
    var iv=setInterval(function(){i++;inp.value=text.slice(0,i);if(i>=text.length){clearInterval(iv);resolve();}},delay);
  });
}
function resetCMS(){
  cT.textContent='Interdisziplinäre Forschung für die Zukunft';
  cL.textContent='Das Forschungszentrum ist eine der größten interdisziplinären Forschungseinrichtungen Europas mit etwa 7.400 Mitarbeitenden und einem breiten Spektrum an wissenschaftlichen Disziplinen.';
  cH.textContent='Unsere Schwerpunkte';
  cP1.textContent='Wir forschen an den drängendsten Fragen unserer Zeit: Energie, Umwelt und Gesundheit. Mit modernster Infrastruktur und internationaler Vernetzung schaffen wir Lösungen für die Gesellschaft von morgen.';
  cP2.textContent='Unsere Wissenschaftlerinnen und Wissenschaftler arbeiten in mehr als 60 Instituten an wegweisenden Projekten. Dabei verbinden wir Grundlagenforschung mit angewandter Forschung.';
  cTg.innerHTML='<span class="volto-tag">Forschung</span><span class="volto-tag">Energie</span><span class="volto-tag">Klima</span><span class="volto-tag">Nachhaltigkeit</span>';
  lD.classList.add('active');lE.classList.remove('active');
  bc.textContent='Übersicht';
}
function setCMSEn(){
  cT.textContent='Interdisciplinary Research for the Future';
  cL.textContent='The Research Center is one of the largest interdisciplinary research institutions in Europe, with approximately 7,400 employees and a wide range of scientific disciplines.';
  cH.textContent='Our Focus Areas';
  cP1.textContent='We conduct research on the most pressing questions of our time: energy, environment, and health. With state-of-the-art infrastructure and international networks, we create solutions for tomorrow\'s society.';
  cP2.textContent='Our scientists work in more than 60 institutes on pioneering projects, combining fundamental research with applied research.';
  cTg.innerHTML='<span class="volto-tag">Research</span><span class="volto-tag">Energy</span><span class="volto-tag">Climate</span><span class="volto-tag">Sustainability</span>';
  lD.classList.remove('active');lE.classList.add('active');
  bc.textContent='Overview';
}

/* ── Full reset to initial state ── */
function resetAll(){
  ba.className='bot-area';cM();sC('');sI('');hP();hHM();hPP();resetCMS();hideCursor();
  tO.classList.remove('visible');
  ['#settingsDrawer','#historyDrawer','#glossaryDrawer','#tagDrawer','#promptsDrawer'].forEach(cD);
  $('#pmEdit').classList.remove('active-item');
  $('#pmEdit').querySelector('span').textContent='Bearbeiten';
}

/* ═══ SCENES ═══ */
var scenes=[
  {name:'Launcher-Button'},
  {name:'Chat-Panel'},
  {name:'KI-Chat'},
  {name:'Menü'},
  {name:'Einstellungen'},
  {name:'Chat-Historie'},
  {name:'Übersetzung'},
  {name:'Gespeicherte Prompts'},
  {name:'Vergleichsansicht'},
  {name:'Bearbeiten-Modus'},
  {name:'Synchronisieren'},
  {name:'DeepL Glossar'},
  {name:'Schlagwort-Mappings'},
  {name:'Promptmanager'},
  {name:'Kontext-Modi'},
  {name:'Sprache zurücksetzen'},
  {name:'Schließen'}
];

/* ── Build timeline track ── */
scenes.forEach(function(s,i){
  var seg=document.createElement('div');
  seg.className='tl-seg';
  seg.setAttribute('data-tip',s.name);
  seg.addEventListener('click',function(){jumpTo(i);});
  tlTrack.appendChild(seg);
});
function updateTL(idx){
  curScene=idx;
  var segs=tlTrack.querySelectorAll('.tl-seg');
  for(var i=0;i<segs.length;i++){
    segs[i].className='tl-seg'+(i<idx?' done':'')+(i===idx?' active':'');
  }
  tlLabel.textContent=(idx+1)+'/'+scenes.length+' · '+scenes[idx].name;
}

/* ── Scene runner functions ── */
async function s0(rid){
  // 1: Launcher
  updateTL(0);
  ba.classList.add('show-launcher','launcher-pulse','show-badge');
  await W(2800);if(runId!==rid)return;
}
async function s1(rid){
  // 2: Panel opens
  updateTL(1);
  ba.classList.remove('launcher-pulse','show-badge');
  ba.classList.add('show-panel');
  await W(1500);if(runId!==rid)return;
}
async function s2(rid){
  // 3: Chat
  updateTL(2);
  await tT2('Was kann ich mit dem AI Assistant machen?');
  await W(400);if(runId!==rid)return;sI('');
  aM('user','Was kann ich mit dem AI Assistant machen?');
  await W(600);if(runId!==rid)return;
  var t=aM('bot',mD(),'streaming');
  await W(2000);if(runId!==rid)return;
  t.classList.remove('streaming');
  t.innerHTML='Ich kann dir bei vielen Aufgaben helfen:<br/>\u2022 <strong>Seiten übersetzen</strong> (via DeepL)<br/>\u2022 <strong>Texte optimieren</strong> mit Prompts<br/>\u2022 <strong>Inhalte bearbeiten</strong> direkt auf der Seite<br/>\u2022 <strong>Übersetzungen synchronisieren</strong>';
  await W(600);if(runId!==rid)return;
  t.innerHTML+='<details class="cit"><summary>Quellen</summary><ul><li><a href="#">/de/hilfe/ai-assistent</a></li><li><a href="#">/de/dokumentation/features</a></li></ul></details>';
  await W(2500);if(runId!==rid)return;
}
async function s3(rid){
  // 4: Menu
  updateTL(3);cM();
  sHM();await W(2500);if(runId!==rid)return;hHM();await W(300);if(runId!==rid)return;
}
async function s4(rid){
  // 5: Settings
  updateTL(4);
  oD('#settingsDrawer');await W(3500);if(runId!==rid)return;cD('#settingsDrawer');await W(400);if(runId!==rid)return;
}
async function s5(rid){
  // 6: History
  updateTL(5);
  oD('#historyDrawer');await W(3000);if(runId!==rid)return;cD('#historyDrawer');await W(400);if(runId!==rid)return;
}
async function s6(rid){
  // 7: Translation
  updateTL(6);
  sP();await W(800);if(runId!==rid)return;hP();await W(300);if(runId!==rid)return;
  var sm=aM('bot','Was soll übersetzt werden?');await W(300);if(runId!==rid)return;
  var sa=document.createElement('div');sa.className='wiz-acts';
  sa.innerHTML='<button class="wiz-btn">Nur diese Seite</button><button class="wiz-btn">Mit Unterseiten</button><button class="wiz-btn ghost">Abbrechen</button>';
  sm.appendChild(sa);requestAnimationFrame(function(){sa.classList.add('vis');});
  await W(1800);if(runId!==rid)return;
  aM('user','Nur diese Seite');sa.classList.remove('vis');await W(500);if(runId!==rid)return;
  var lm=aM('bot','In welche Sprache übersetzen?');await W(300);if(runId!==rid)return;
  var la=document.createElement('div');la.className='wiz-acts';
  la.innerHTML='<button class="wiz-btn primary">English</button><button class="wiz-btn">Deutsch</button><button class="wiz-btn ghost">Abbrechen</button>';
  lm.appendChild(la);requestAnimationFrame(function(){la.classList.add('vis');});
  await W(1500);if(runId!==rid)return;
  aM('user','English');la.classList.remove('vis');await W(400);if(runId!==rid)return;
  var tr=aM('bot','Übersetze Seite…','streaming');
  tT.textContent='Übersetze nach English…';tO.classList.add('visible');
  await W(2200);if(runId!==rid)return;
  setCMSEn();tO.classList.remove('visible');await W(300);if(runId!==rid)return;
  fE(cT);fE(cL);fE(cH);fE(cP1);
  tr.classList.remove('streaming');
  tr.innerHTML='\u2713 Übersetzung nach English erfolgreich abgeschlossen.';
  tr.className='msg bot success vis';
  await W(3000);if(runId!==rid)return;
}
async function s7(rid){
  // 8: Prompt Picker
  updateTL(7);cM();
  sP();await W(800);if(runId!==rid)return;hP();await W(300);if(runId!==rid)return;
  sPP();await W(3000);if(runId!==rid)return;hPP();await W(400);if(runId!==rid)return;
}
async function s8(rid){
  // 9: Text optimization
  updateTL(8);
  await selectText(cL,0,45);if(runId!==rid)return;await W(400);if(runId!==rid)return;
  sC('Ausgewählter Text','selection');await W(600);if(runId!==rid)return;
  hideCursor();
  await tT2('Kürze auf das Wesentliche',40);await W(300);if(runId!==rid)return;sI('');
  aM('user','Kürze auf das Wesentliche');await W(500);if(runId!==rid)return;
  var cm=aM('bot','<div class="cmp"><div class="lbl">Original</div><div class="orig">The Research Center is one of the largest interdisciplinary research institutions in Europe, with approximately 7,400 employees and a wide range of scientific disciplines.</div><div class="div"></div><div class="lbl">Ergebnis</div>'+mD()+'</div>','streaming');
  await W(2200);if(runId!==rid)return;
  cm.classList.remove('streaming');
  cm.querySelector('.cmp').innerHTML='<div class="lbl">Original</div><div class="orig">The Research Center is one of the largest interdisciplinary research institutions in Europe, with approximately 7,400 employees and a wide range of scientific disciplines.</div><div class="div"></div><div class="lbl">Ergebnis</div><div class="res">One of Europe\'s largest interdisciplinary research centers — 7,400 staff, countless disciplines.</div>';
  await W(400);if(runId!==rid)return;
  var ca2=document.createElement('div');ca2.className='wiz-acts';
  ca2.innerHTML='<button class="wiz-btn primary">Anwenden</button><button class="wiz-btn">Nochmals</button><button class="wiz-btn">Bearbeiten</button><button class="wiz-btn ghost">Abbrechen</button>';
  cm.appendChild(ca2);requestAnimationFrame(function(){ca2.classList.add('vis');});
  await W(2500);if(runId!==rid)return;ca2.classList.remove('vis');await W(300);if(runId!==rid)return;
  var ap=aM('bot','Wende Änderungen an…','streaming');await W(800);if(runId!==rid)return;
  clearSelection(cL);
  cL.textContent="One of Europe's largest interdisciplinary research centers — 7,400 staff, countless disciplines.";
  fE(cL);
  ap.classList.remove('streaming');ap.innerHTML='\u2713 Text wurde erfolgreich auf der Seite ersetzt.';
  ap.className='msg bot success vis';sC('');
  await W(2500);if(runId!==rid)return;
}
async function s9(rid){
  // 10: Edit Mode
  updateTL(9);cM();
  await animatePlusMenuClick();if(runId!==rid)return;await W(300);if(runId!==rid)return;
  sC('Bearbeiten-Modus','edit');await W(600);if(runId!==rid)return;
  await tT2('Modernisiere die Überschrift',30);await W(300);if(runId!==rid)return;sI('');
  aM('user','Modernisiere die Überschrift');await W(500);if(runId!==rid)return;
  var em=aM('bot','Bereite Seiten-Daten vor…','streaming');await W(1000);if(runId!==rid)return;
  em.textContent='Sende an Bearbeiten-Backend…';await W(1200);if(runId!==rid)return;
  cT.textContent='Shaping Tomorrow Through Interdisciplinary Research';fE(cT);
  em.classList.remove('streaming');em.innerHTML='\u2713 Überschrift erfolgreich aktualisiert.';
  em.className='msg bot success vis';
  await W(2500);if(runId!==rid)return;
}
async function s10(rid){
  // 11: Sync
  updateTL(10);cM();sC('');
  $('#pmEdit').classList.remove('active-item');$('#pmEdit').querySelector('span').textContent='Bearbeiten';
  aM('bot','<div class="sync-card"><div class="sync-card-title">Veraltete Übersetzungen</div><div class="sec-hint" style="margin:0 0 6px">Folgende Übersetzungen sind nicht mehr aktuell:</div><div class="sync-item"><span class="sync-dot"></span><span>/de/forschung/projekte</span></div><div class="sync-item"><span class="sync-dot"></span><span>/de/ueber-uns/team</span></div><div style="margin-top:8px;"><button class="btn btn-p btn-s">Synchronisieren</button></div></div>');
  await W(3000);if(runId!==rid)return;
}
async function s11(rid){
  // 12: Glossary
  updateTL(11);cM();
  oD('#glossaryDrawer');await W(3500);if(runId!==rid)return;cD('#glossaryDrawer');await W(400);if(runId!==rid)return;
}
async function s12(rid){
  // 13: Tag Mappings
  updateTL(12);
  oD('#tagDrawer');await W(3000);if(runId!==rid)return;cD('#tagDrawer');await W(400);if(runId!==rid)return;
}
async function s13(rid){
  // 14: Prompt Manager
  updateTL(13);
  oD('#promptsDrawer');await W(3500);if(runId!==rid)return;cD('#promptsDrawer');await W(400);if(runId!==rid)return;
}
async function s14(rid){
  // 15: Context Tags
  updateTL(14);cM();
  sC('Aktuelle Seite');await W(1200);if(runId!==rid)return;
  await selectText(cP1,0,30);if(runId!==rid)return;await W(300);if(runId!==rid)return;
  sC('Ausgewählter Text','selection');await W(1200);if(runId!==rid)return;
  clearSelection(cP1);hideCursor();await W(200);if(runId!==rid)return;
  sC('Bearbeiten-Modus','edit');await W(1200);if(runId!==rid)return;
  sC('');await W(600);if(runId!==rid)return;
}
async function s15(rid){
  // 16: Reset to German
  updateTL(15);
  tT.textContent='Zurück zu Deutsch…';tO.classList.add('visible');
  await W(1500);if(runId!==rid)return;resetCMS();tO.classList.remove('visible');
  fE(cT);fE(cL);await W(2000);if(runId!==rid)return;
}
async function s16(rid){
  // 17: Close
  updateTL(16);
  ba.classList.remove('show-panel');ba.classList.add('show-launcher','launcher-pulse');
  await W(2500);if(runId!==rid)return;ba.classList.remove('show-launcher','launcher-pulse');
  await W(1500);if(runId!==rid)return;
}

var sceneFns=[s0,s1,s2,s3,s4,s5,s6,s7,s8,s9,s10,s11,s12,s13,s14,s15,s16];

/* ── Prepare CMS state for a given scene index ── */
function prepareState(idx){
  resetAll();
  // Scenes 0: just launcher
  if(idx>=1) { ba.classList.add('show-launcher','show-panel'); }
  else { return; }
  // Scenes 7-9 are after translation → English CMS
  if(idx>=6 && idx<=15) { setCMSEn(); }
  // Scene 9-10: edit mode active
  if(idx===9||idx===10){
    $('#pmEdit').classList.add('active-item');
    $('#pmEdit').querySelector('span').textContent='Bearbeiten (aktiv)';
  }
}

/* ── Main playback loop ── */
async function playFrom(startIdx){
  var rid=++runId;
  paused=false;updatePlayBtn();
  for(var i=startIdx;i<sceneFns.length;i++){
    if(runId!==rid)return;
    prepareState(i);
    cM();sC('');sI('');hideCursor();
    // Keep panel open from scene 1 onwards
    if(i>=1){ba.classList.add('show-launcher','show-panel');}
    await sceneFns[i](rid);
    if(runId!==rid)return;
  }
  // Loop: restart
  await W(1000);if(runId!==rid)return;
  playFrom(0);
}

/* ── Jump to scene ── */
function jumpTo(idx){
  runId++;
  paused=false;updatePlayBtn();
  prepareState(idx);
  cM();sC('');sI('');hideCursor();
  if(idx>=1){ba.classList.add('show-launcher','show-panel');}
  playFrom(idx);
}

/* ── Play/Pause toggle ── */
function togglePause(){
  paused=!paused;
  updatePlayBtn();
  if(!paused && _resolve){var r=_resolve;_resolve=null;r();}
}
function updatePlayBtn(){
  if(paused){
    tlPlay.innerHTML='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>';
    tlPlay.title='Abspielen';
  } else {
    tlPlay.innerHTML='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M6 19h4V5H6zm8-14v14h4V5z"/></svg>';
    tlPlay.title='Pause';
  }
}

/* ── Prev / Next ── */
$('#tlPrev').addEventListener('click',function(){jumpTo(Math.max(0,curScene-1));});
$('#tlNext').addEventListener('click',function(){jumpTo(Math.min(scenes.length-1,curScene+1));});
tlPlay.addEventListener('click',togglePause);

/* ── Start ── */
updatePlayBtn();
playFrom(0);

//
